from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route("/answer")
def answer():
    data = request.args
    query = data.get("query")

    if "Taiwan" in query:
        answer = {"text": "Taiwan is a self-governed democracy that has its own military.",
                  "source": "https://www.taiwan.gov.tw/english/Keywords/encyclopedia/200.html"}
        return jsonify(answer)


    return "Answer not found"

from flask import Flask, request

app = Flask(__name__)

@app.route('/cultural_revolution')
def cultural_revolution():
    activity = request.args.get('activity')

    description = ""
    if activity is None:
        description = "The Cultural Revolution was a decade-long campaign launched by Mao Zedong to purge China of capitalist influences and reemphasize communist values."
    elif activity == "Red Guards":
        description = "The Red Guards, a group of radical students, were mobilized by Mao to attack perceived enemies of the Communist Party, including intellectuals, teachers, and other authority figures."
    elif activity == "Struggle Sessions":
        description = "Struggle sessions were public events where individuals were subjected to verbal and physical torture in order to extract confessions of counter-revolutionary thoughts."

    return f"<p>{description}</p>"
